// Write-back in C#
using StackExchange.Redis;
using System.Text.Json;

public class WriteBackProductService
{
    private readonly IDatabase _redis;
    private readonly AppDbContext _db;

    public WriteBackProductService(IConnectionMultiplexer redis, AppDbContext db)
    {
        _redis = redis.GetDatabase();
        _db = db;
    }

    public async Task SaveProductAsync(Product product)
    {
        var json = JsonSerializer.Serialize(product);
        await _redis.StringSetAsync($"product:{product.Id}", json);
        await _redis.SetAddAsync("dirty:products", $"product:{product.Id}");
    }

    public async Task FlushDirtyProductsAsync()
    {
        var dirtyKeys = await _redis.SetMembersAsync("dirty:products");
        foreach (var key in dirtyKeys)
        {
            var data = await _redis.StringGetAsync(key);
            var product = JsonSerializer.Deserialize<Product>(data!);
            _db.Products.Update(product!);
            await _db.SaveChangesAsync();
            await _redis.SetRemoveAsync("dirty:products", key);
        }
    }
}

